export const LEARN_TOPICS: LearnTopic[] = [{"id":"what-is-ai","topic":"What is AI? · The Big Picture","description":"Understand what Artificial Intelligence actually is, its history, different types (narrow vs general AI), and where it's headed. Get the mental map before diving into code.","phase":"foundations","difficulty":"beginner","order":1,"week":1,"tools":"ChatGPT, Claude, Google Gemini, try using AI first to understand what it can do before learning how it works","proTips":"Don't jump into code yet. Spend Week 1 just understanding the landscape. Watch videos, read articles, and form your own mental model of what AI is and isn't.","resources":["r0e567dae7","rdb5ebd2f0","rfa510d647","rb1a49faa5","r619964b67","r6399a72a2","rfa2f2df2e","rfb83990d5","rd03705c14","r2567bb394","rc9fdf064b","r54bbf4fb0","r3eadfa87a"]},{"id":"python","topic":"Python Programming for AI","description":"Python is THE language for AI/ML. Learn core Python: variables, loops, functions, classes, list comprehensions, file I/O. You don't need to be an expert, just comfortable enough to write and read code.","phase":"python-math","difficulty":"beginner","order":2,"week":2,"tools":"VS Code, Google Colab (free GPU!), Jupyter Notebooks, Replit","proTips":"Focus on: lists, dictionaries, functions, loops, and classes. Practice on LeetCode Easy or HackerRank. Google Colab is your best friend, free, browser-based, no setup needed. And if you are weighing Python against R: Python won for AI and production systems, R remains lovely for pure statistics.","resources":["r99fbc003c","re1ffee8a0","r9b85a8784","r0a2eefbd6","rc7aefdcbb","r49505b106","rb4bfbfa36","r2262a0147","r7aed151cc","rdfc22ee6f","rbe5a72b06","rbd522ee86","r0e50846a7","rab0b739e8","r98003baeb"]},{"id":"math","topic":"Math for AI · Linear Algebra & Calculus","description":"You need just enough math to understand what's happening inside ML models. Key concepts: vectors, matrices, matrix multiplication (linear algebra), derivatives and gradients (calculus). You do NOT need a math degree.","phase":"python-math","difficulty":"beginner","order":3,"week":3,"tools":"NumPy (practice matrix ops in code), Desmos (graph visualizer), GeoGebra, Wolfram Alpha","proTips":"Don't get stuck here for months. Spend 1-2 weeks getting the intuition from 3Blue1Brown videos, then move on. You'll reinforce the math naturally as you code ML models. Intuition > memorization.","resources":["r0d917c44e","rb166f5dae","r911193eae","r0c6fdb9e0","r1a19bcd2f","r02442ea8e","r9b3dc9eca","r7ffa44b1c","r704875793","rccc82005a","r048a20f4f","rb4cee3c98","r62b78b325"]},{"id":"statistics","topic":"Statistics & Probability for ML","description":"Core statistics you'll need: distributions (normal, uniform), mean/median/mode, standard deviation, correlation, hypothesis testing, Bayes' theorem, probability basics. These concepts underpin every ML algorithm.","phase":"python-math","difficulty":"beginner","order":3.5,"week":4,"tools":"SciPy (scipy.stats), statsmodels, Seeing Theory (interactive visualizations)","proTips":"StatQuest on YouTube is the single best resource for statistics. Josh Starmer explains everything with humor and clarity. Watch his playlists before touching any textbook.","resources":["re789e72ad","r5658bc1c1","re96520cf6","r98a7b4df5","r29d392f76","r666ea8601","r8e8f31b9b","r78e384119","r90b6ad2f2","rf206c1460","rb71eeb1ef","r17c82faa5","rf9b7ed6ba"]},{"id":"numpy-pandas","topic":"NumPy, Pandas & Data Visualization","description":"The essential Python data stack. NumPy for numerical computing and arrays, Pandas for data manipulation and analysis, Matplotlib/Seaborn for visualization. These are used in every single ML project.","phase":"python-math","difficulty":"beginner","order":4,"week":4,"tools":"Google Colab, Jupyter Notebooks, Kaggle Notebooks (free GPU), VS Code with Python extension","proTips":"Download a real dataset from Kaggle and play with it. Load it in Pandas, explore with .head(), .describe(), .value_counts(). Plot charts. This hands-on experience is worth more than 10 tutorials.","resources":["rd11ca09d7","r7ae308fb1","rc5d4df141","r71623eca8","r1abca2577","r2f29ae228","r9b119ea6a","r628c21edb","rce84ea873","r34d66d0f5","r9dde8e2e7","rf9f05882f","r78e319633"]},{"id":"data-engineering","topic":"Data Engineering & Data Pipelines for AI","description":"Real AI projects need real data pipelines. Learn data cleaning, missing value handling, feature scaling, encoding categorical variables, data augmentation, SQL basics, and working with APIs. Garbage in = garbage out, data quality is 80% of ML success.","phase":"machine-learning","difficulty":"intermediate","order":4.5,"week":5,"tools":"Pandas, SQL (PostgreSQL, SQLite), Apache Airflow, dbt, Great Expectations, ydata-profiling","proTips":"Data scientists spend 60-80% of their time on data preparation. Master Pandas deeply: .merge(), .groupby(), .pivot_table(), .apply(), handling missing values with .fillna() and .interpolate(). Learn basic SQL, most ML data comes from databases.","resources":["rc9e7bc18e","r5a6431329","r0f157e02f","ra355c630c","r185f59ca0","ra3eedbad8","r9e38242d1","rce84ea873","r7bd602fed","r5e3363298","r8c09f260f","rc70839f11","r30736edb3"]},{"id":"intro-ml","topic":"Intro to Machine Learning","description":"The core ML concepts: supervised vs unsupervised learning, regression, classification, train/test splits, overfitting, bias-variance tradeoff. This is where everything comes together, your Python, math, and data skills meet ML algorithms.","phase":"machine-learning","difficulty":"intermediate","order":5,"week":5,"tools":"scikit-learn (primary ML library), Google Colab, Kaggle (start competing!), Weights & Biases (experiment tracking)","proTips":"Start with scikit-learn, NOT TensorFlow/PyTorch. Build simple models first: Linear Regression → Logistic Regression → Decision Trees → Random Forest. Do Kaggle's Titanic competition, it's the Hello World of ML.","resources":["rd8d809a8a","r8107caf18","r735b03ab6","re108a8e56","r2127f1c84","r2692fb62b","rc77b41f32","ra02750547","rf788642ea","rb3ca1b52f","r61bb3ae44","r80c37ff58","r69b0fac56","r8fb9a326b"]},{"id":"model-evaluation","topic":"Model Evaluation & Experiment Tracking","description":"How do you know if your model is actually good? Learn evaluation metrics (accuracy, precision, recall, F1, AUC-ROC, RMSE, MAE), confusion matrices, learning curves, cross-validation, A/B testing, and experiment tracking with MLflow/W&B.","phase":"machine-learning","difficulty":"intermediate","order":5.5,"week":6,"tools":"scikit-learn metrics, Weights & Biases, MLflow, TensorBoard, Optuna (hyperparameter tuning)","proTips":"NEVER just use accuracy, it's misleading for imbalanced datasets. Learn when to use precision vs recall (hint: false positives vs false negatives have different costs). Start tracking experiments from day 1 with Weights & Biases, it's free for individuals.","resources":["rb6a908daa","rd5bcbcf01","rc87f4ec60","r38ff3f8a9","rbedf9e676","rc77b41f32","r51a568afa","rf788642ea","rb3ca1b52f","rbf543877b","r74d7825ed","r76bc22047","r41fff2744"]},{"id":"sklearn-projects","topic":"Scikit-Learn & Hands-On ML Projects","description":"Get hands dirty with real ML projects. Learn the scikit-learn workflow: load data → preprocess → feature engineering → model selection → train → evaluate → tune hyperparameters. Practice on real Kaggle competitions.","phase":"machine-learning","difficulty":"intermediate","order":6,"week":6,"tools":"scikit-learn, XGBoost, LightGBM, Kaggle Notebooks, Weights & Biases, Optuna (hyperparameter tuning)","proTips":"Do at least 3 Kaggle competitions: Titanic (classification), House Prices (regression), and one tabular playground. Read winning solutions, they teach you more than any course.","resources":["rd5b59b83f","r81970cf38","rc87f4ec60","r7cdeab295","rf428605c6","r93a3bae9f","rb3a41a79f","rf788642ea","rdf6724581","r0559479bd","r86440b2c4","r4c312e92f"]},{"id":"milestone-ml","topic":"🧪 PRACTICE MILESTONE: Build Your First ML Project","description":"STOP and BUILD. Don't move to Deep Learning until you've completed at least 2 hands-on projects. This is where most learners fail, they watch videos endlessly but never code. Build a complete ML pipeline from scratch: data collection → EDA → feature engineering → model training → evaluation → deployment.","phase":"machine-learning","difficulty":"intermediate","order":6.5,"week":7,"milestone":true,"tools":"Kaggle Notebooks, Google Colab, Streamlit, Gradio, scikit-learn","proTips":"MUST-DO: ① Titanic Survival Prediction (classification) ② House Price Prediction (regression) ③ Customer Churn Analysis (real business problem) ④ Build a web app with Streamlit showing your model.","resources":["r14d8e5bfb","r814e76389","r296a3e7ba","r1baeba48f","r1f68b28f1","rb98b6f30f","rd370164fe","rf788642ea","rdf6724581","r0559479bd","r1d43582ef","r082c3f5e4"]},{"id":"neural-networks","topic":"Neural Networks & Deep Learning Fundamentals","description":"The jump from classical ML to deep learning. Understand neurons, layers, activation functions, forward/backward propagation, loss functions, and gradient descent. This is the foundation for everything modern in AI, from ChatGPT to self-driving cars.","phase":"deep-learning","difficulty":"intermediate","order":7,"week":7,"tools":"PyTorch (recommended), TensorFlow/Keras, Google Colab (free GPU), Weights & Biases","proTips":"Start with 3Blue1Brown's 4-part neural network series, it gives you the visual intuition that textbooks can't. Then move to fast.ai which teaches top-down (build working models first, understand theory after). Choose PyTorch over TensorFlow for learning.","resources":["r83bc4a056","r2ae8fd5d4","r8df50f8ee","rba30d7f0a","r2692fb62b","r99d4689a9","r6e38a4138","rd119f19bf","rc86246e63","rf52381dbd","r4f870d260","r80260b283","ra18c408c5"]},{"id":"pytorch","topic":"PyTorch · The Deep Learning Framework","description":"PyTorch is the #1 deep learning framework used in research and increasingly in production. Learn tensors, autograd, building models with nn.Module, training loops, data loaders, and GPU acceleration.","phase":"deep-learning","difficulty":"intermediate","order":8,"week":8,"tools":"PyTorch, PyTorch Lightning, Google Colab (free GPU/TPU), Weights & Biases (experiment tracking), Hugging Face (model hub)","proTips":"Andrej Karpathy's 'Neural Networks: Zero to Hero' playlist is the single best resource for learning deep learning from scratch. He builds everything from raw Python, no library shortcuts. Watch it all.","resources":["r5ad8bb89c","r16d8bfcc6","r67cc04427","ra414ee436","r5581ef62b","r2692fb62b","rebc65d68c","rc9c221b22","rc86246e63","r0425fac9a","r215085328","r138525fe3","r043bce6f1","ra18c408c5"]},{"id":"cnns","topic":"CNNs & Computer Vision","description":"Convolutional Neural Networks (CNNs) are how AI 'sees'. Learn convolution operations, pooling, classic architectures (LeNet, AlexNet, VGG, ResNet), transfer learning, and image classification/detection/segmentation.","phase":"deep-learning","difficulty":"intermediate","order":9,"week":9,"tools":"torchvision, OpenCV, Albumentations, Roboflow (data labeling), Hugging Face (pretrained models)","proTips":"Don't build from scratch, use transfer learning. Take a pretrained ResNet or EfficientNet from torchvision, freeze early layers, fine-tune on your data. You'll get 95%+ accuracy on most image tasks with very little data.","resources":["r7091bf062","r9606a38a1","r62cb97b7e","r666904a41","r7c8777c81","r59f5e9979","rcd247fa9c","rc3ba43705","r565ec6c03","rf788642ea","r53ed94114","rb1a965c8f","r0e77f8a58"]},{"id":"rnns","topic":"RNNs, LSTMs & Sequence Models","description":"Recurrent Neural Networks process sequential data, text, time series, audio. Learn vanilla RNNs, the vanishing gradient problem, LSTMs, GRUs, and seq2seq models. These were the foundation before Transformers took over.","phase":"deep-learning","difficulty":"intermediate","order":10,"week":10,"tools":"PyTorch (nn.LSTM, nn.GRU), TensorFlow/Keras, Google Colab","proTips":"RNNs/LSTMs are largely being replaced by Transformers, but understanding them is crucial for the historical context and for time-series problems where they still shine. Read Chris Olah's LSTM blog post, it's the best explanation ever written.","resources":["r047062f25","r369600ad3","rf7fa60aa0","r6698d79b6","r95793dd75","r6499f739a","r422945e2b","r7adac431d","r3a806877d","r6f2166862","r21dda50e9"]},{"id":"transformers","topic":"Transformers & Attention Mechanism","description":"THE architecture that changed everything. Understand self-attention, multi-head attention, positional encoding, encoder-decoder structure. Transformers power GPT, BERT, Claude, Stable Diffusion, and nearly all modern AI.","phase":"deep-learning","difficulty":"advanced","order":11,"week":11,"tools":"Hugging Face Transformers, PyTorch, Google Colab, Weights & Biases","proTips":"This is the most important topic in modern AI. Karpathy's 'Let's build GPT from scratch' video (2hrs) is THE best way to learn it, he codes a working GPT character by character. Pair it with Jay Alammar's Illustrated Transformer blog post for the visual intuition.","resources":["r6bdfd045a","r8cbc2327d","r3ecc13ff4","r562e5f7e9","rec24e71bb","r671ad150b","r2aa762c4a","rf36a7ac14","r71aa780a8","r32b9d4c78","r29ec509c1","rbee552534","r9a589f3bd","r1336405fa","r718e21a93"]},{"id":"milestone-dl","topic":"🏗️ PRACTICE MILESTONE: Deep Learning Projects","description":"BUILD before moving to NLP. Complete at least 2 deep learning projects: one in computer vision and one sequence/text task. Deploy at least one model as a live web app. This proves you can actually ship, not just watch tutorials.","phase":"deep-learning","difficulty":"advanced","order":11.5,"week":12,"milestone":true,"tools":"PyTorch, Hugging Face Spaces, Gradio, FastAPI, Docker, Google Colab","proTips":"MUST-DO: ① Image classifier with transfer learning ② Text sentiment analyzer using RNNs or fine-tuned BERT ③ Neural network from SCRATCH ④ Deploy one project to Hugging Face Spaces.","resources":["r3de5cfb1b","r040762b73","r88aa1a615","r3086a5fec","r4572bfae9","re9a5fa5ed","rf788642ea","rc86246e63","r138525fe3","r082c3f5e4","r9a589f3bd"]},{"id":"nlp","topic":"NLP & Text Processing Fundamentals","description":"Natural Language Processing, how AI understands text. Learn tokenization, word embeddings (Word2Vec, GloVe), text preprocessing, sentiment analysis, named entity recognition, and text classification. The stepping stones to LLMs.","phase":"nlp-llms","difficulty":"intermediate","order":12,"week":12,"tools":"Hugging Face, spaCy, NLTK, Google Colab, Kaggle","proTips":"Start with Hugging Face's free NLP course, it's practical and modern. spaCy is the go-to library for production NLP. For learning, the Stanford CS224n lectures are unmatched in depth.","resources":["rf7c1892b6","r8011b4b70","r47f3db5e5","r2fd694b1c","raa5b9c1e5","rf36a7ac14","rcb4474299","r2d7ef1a38","r4ec2b0f4f","rb80dc8147","r9a589f3bd","re5119142e","r58f07739d","r6f2166862"]},{"id":"prompt-engineering","topic":"Prompt Engineering & Using LLMs Effectively","description":"Before building LLMs, learn to USE them expertly. Prompt engineering is the #1 most practical AI skill in 2025-2026. Learn zero-shot, few-shot, chain-of-thought, ReAct prompting, system prompts, structured outputs, and how to get consistent, reliable results from any LLM.","phase":"nlp-llms","difficulty":"intermediate","order":12.5,"week":13,"tools":"Claude, ChatGPT, Gemini, Anthropic Workbench, OpenAI Playground, Prompt IDE tools","proTips":"The most underrated AI skill. Start with Anthropic's prompt engineering guide, it's the best practical resource. Key techniques: (1) Be specific and structured (2) Use XML tags (3) Chain-of-thought for reasoning (4) Few-shot examples (5) System prompts. Practice daily.","resources":["r5d25620c9","rdcfc444e4","rb67ce86da","r0baa3472c","r508508a2c","r2e73c8011","r57ac1f4ef","rfa53afcc3","r5bd403a2f","r961610bd6","r7d50b5f57","rfd9854aa4","r7592adc74","r2a8e47c5f"]},{"id":"llms","topic":"Large Language Models (LLMs) · GPT, BERT & Beyond","description":"The era of LLMs. Understand how GPT, BERT, Claude, Llama, and other LLMs work. Learn pre-training, fine-tuning, prompt engineering, RLHF, in-context learning, emergent abilities, and the scaling laws that make them powerful.","phase":"nlp-llms","difficulty":"advanced","order":13,"week":13,"tools":"Hugging Face, Ollama (run local LLMs), OpenAI API, Anthropic API, LangChain, vLLM","proTips":"Karpathy's LLM intro talk is the best 1-hour overview that exists. Then try running a model locally with Ollama (literally one command). Understanding how to USE LLMs well (prompt engineering) is just as important as understanding how they work internally.","resources":["r64296c96e","r3ecc13ff4","r63388c49d","r3a42516dd","ra21885e6d","r7e163ae2a","r4973d330f","r9010925eb","r449543a47","r89c40dc1a","rf36a7ac14","ra61ab06e4","r9f7192875","r6daf2d5f3","rbee552534","r6af93ea43","r6fae0bda3","r221b3f216"]},{"id":"fine-tuning-rag","topic":"Fine-Tuning & RAG · Customizing LLMs","description":"Make LLMs work for YOUR use case. Learn fine-tuning (LoRA, QLoRA), Retrieval-Augmented Generation (RAG), vector databases, embeddings, prompt engineering patterns, and building LLM-powered applications.","phase":"nlp-llms","difficulty":"advanced","order":14,"week":14,"tools":"LangChain, LlamaIndex, ChromaDB, Pinecone, Weaviate, Hugging Face PEFT, Ollama, OpenAI API","proTips":"RAG is the most practical skill for 2025-2026. It lets you connect LLMs to your own data without expensive fine-tuning. Start by building a simple RAG app: embed your documents in ChromaDB, retrieve relevant chunks, pass to an LLM. LangChain or LlamaIndex make this easy.","resources":["ra174f1eb6","rc80ad75a9","r9cdf586d5","r59e59391f","rf113dd718","rf69cb28d5","r8aeb2a90b","r51d1f9853","rcbacad3a7","r7a22705a7","rc817fe61f","r6299c10bb","r2f4fb6238","r09ff9103f","r6c5b4f8bf","rcc411a4bf"]},{"id":"milestone-llm","topic":"🚀 PRACTICE MILESTONE: Build & Deploy an LLM App","description":"The capstone practice before specializing. Build a complete LLM-powered application: a RAG chatbot, an AI agent, a document Q&A system, or a writing assistant. Deploy it live. This is the project that gets you hired in 2025-2026.","phase":"nlp-llms","difficulty":"advanced","order":14.5,"week":15,"milestone":true,"tools":"LangChain, LlamaIndex, ChromaDB, Streamlit, Gradio, Hugging Face Spaces, Vercel, Railway","proTips":"MUST-DO: ① Document Q&A Bot, Upload PDFs, ask questions (RAG) ② AI Writing Assistant, Custom persona + style ③ Multi-tool AI Agent, Can search web, run code, analyze data ④ Deploy to Hugging Face Spaces or Vercel for a live demo URL.","resources":["r9cdf586d5","rcb478a139","rc64bded3b","r335cab527","r51d1f9853","r7704ca40f","rda47eb89e","r88aa1a615","r0b62ad1cf","r7d24e5faa","r2f4fb6238","rcc411a4bf","r1d43582ef","r6c5b4f8bf"]},{"id":"generative-ai","topic":"Generative AI · Images, Audio & Video","description":"Beyond text: learn how AI generates images (Stable Diffusion, DALL-E), audio (speech synthesis, music), and video. Understand diffusion models, GANs, VAEs, and the creative AI revolution.","phase":"specialize","difficulty":"advanced","order":15,"week":15,"tools":"Stable Diffusion, ComfyUI, DALL-E, Midjourney, Runway ML, Whisper (speech-to-text)","proTips":"Diffusion models have largely replaced GANs for image generation. Start by running Stable Diffusion locally with ComfyUI, it's the best way to understand the generation pipeline. For audio, OpenAI's Whisper is incredibly good and open-source.","resources":["r82d1ca1e4","r81d921cfd","r9e976fe9c","r5828bd669","rac3506232","re72a27659","rcc155347f","r8d5da7c12","r36234892e","r40959faa0","rb4efb8e81","rbc4f619e9","r90ad178f8","r4a3141e52"]},{"id":"ai-agents","topic":"AI Agents & Agentic AI","description":"The hottest frontier in AI (2025-2026). AI agents can plan, use tools, browse the web, write code, and complete multi-step tasks autonomously. Learn agent architectures, tool use, memory systems, ReAct pattern, and frameworks like LangGraph and CrewAI.","phase":"specialize","difficulty":"advanced","order":15.5,"week":16,"tools":"LangGraph, CrewAI, AutoGen, Claude with tool use, OpenAI Assistants API, Anthropic Claude Agent SDK","proTips":"AI Agents are where the industry is moving in 2025-2026. Start by building a simple ReAct agent with LangGraph, give an LLM access to a calculator and web search, watch it reason and act. Then build something real: a research agent, a coding assistant, or a data analysis agent.","resources":["r55546b896","ra8c31631d","r7d24e5faa","r052c3b830","r2e64d8614","ra681cbc2e","r2046e661a","rac8be3ea8","rfa53afcc3","rc84005d04","r42745a8e0","r0baffed4a","re2afe39a9","rf46ea0410","rab9a1738e","r54439e748","ra1e2c5f2d","rfa02ad3a6"]},{"id":"mlops","topic":"MLOps & Deploying AI Models","description":"Getting models from notebook to production. Learn model serving (FastAPI, Flask), containerization (Docker), model monitoring, CI/CD for ML, experiment tracking, and cloud deployment (AWS, GCP, Azure).","phase":"specialize","difficulty":"advanced","order":16,"week":16,"tools":"Docker, FastAPI, Gradio, Streamlit, MLflow, Weights & Biases, Hugging Face Spaces, AWS SageMaker, GCP Vertex AI","proTips":"Build a portfolio project end-to-end: train a model, wrap it in FastAPI, containerize with Docker, deploy to Hugging Face Spaces or Railway. Gradio and Streamlit are the fastest ways to create a shareable demo. Chip Huyen's MLOps book is essential reading.","resources":["r96b2e7bd9","r3de5cfb1b","rb3a41a79f","r9cff6afa1","rb00c29612","r98fa80379","re8c34f940","r3d9d50d8b","rbf543877b","r76bc22047","r87c9fd0e9","r52ef64444","r082c3f5e4"]},{"id":"rl","topic":"Reinforcement Learning Deep Dive","description":"Go deeper into RL: Q-learning, Deep Q-Networks (DQN), Policy Gradients, PPO, Actor-Critic methods, and RLHF (how ChatGPT was trained). RL is key to robotics, game AI, and aligning LLMs.","phase":"specialize","difficulty":"advanced","order":16.5,"week":17,"tools":"Gymnasium (OpenAI Gym successor), Stable Baselines3, Hugging Face TRL, Unity ML-Agents","proTips":"David Silver's course is the gold standard for RL theory. For hands-on, use Hugging Face's Deep RL course, you train agents in game environments. Understanding PPO is especially important because it's the algorithm behind RLHF.","resources":["rced3adf65","r567029d27","rf7dd5dced","r659ec3c42","ra37bb3d57","r072410e47","r223472953","re85005a68","ra600ee4c9","ra612902a8","r323851edc","r45e555d36","r56381feed","r8983b7dbf","r30c3b11f0"]},{"id":"portfolio","topic":"Build Your AI Portfolio & Get Hired","description":"Turn your skills into a career. Build 3-5 portfolio projects, contribute to open source, write technical blog posts, compete on Kaggle, and prepare for AI/ML interviews (coding + system design + ML theory).","phase":"specialize","difficulty":"advanced","order":17,"week":17,"tools":"GitHub (portfolio), Kaggle (competitions), Hugging Face Spaces (demos), LinkedIn, Medium/Substack (blogging)","proTips":"Your GitHub IS your resume. Build 3 standout projects: (1) an end-to-end ML app with a live demo, (2) a Kaggle competition with a top 10% finish, (3) a novel project that shows creativity. Write blog posts explaining what you built, this shows communication skills.","resources":["rca220335f","r44a458a75","rf428605c6","re9a5fa5ed","rf4160ee2d","r36030e489","r52e9fd12f","re8c34f940","re950f4980","rc47e458dd","rec3394bcf","re54d29b87"]},{"id":"ai-safety","topic":"AI Safety, Ethics & Responsible AI","description":"The most important topic in AI that most courses skip. Understand bias in AI, fairness, interpretability/explainability (XAI), alignment, AI governance, hallucinations, deepfakes, and responsible deployment. Every AI practitioner needs this knowledge.","phase":"specialize","difficulty":"intermediate","order":17.5,"week":17,"tools":"Fairlearn (bias detection), SHAP (explainability), LIME, AI Fairness 360 (IBM), What-If Tool (Google)","proTips":"This isn't optional anymore. Companies are hiring for Responsible AI roles, and every ML engineer is expected to understand bias, fairness, and safety. The EU AI Act is now law, understanding AI regulation is a career advantage. Read 'Weapons of Math Destruction'.","resources":["r0df92f086","rbb6309c76","rd6a60aee0","r7ab67efe4","r534f9dd30","rde0760333","r3ea79169f","rbb81b6330","r0fb130008","r2de6ee3c9","r55c4412cd","rf93711ed0","r8c376f9c5"]},{"id":"research-papers","topic":"Reading Research Papers & Staying Current","description":"AI moves fast, new papers weekly. Learn how to read ML papers efficiently, stay current with the latest breakthroughs, follow the right researchers, and develop your own research intuition. This separates juniors from seniors.","phase":"specialize","difficulty":"advanced","order":18,"week":18,"tools":"arXiv, Papers With Code, Semantic Scholar, Google Scholar, Zotero (reference manager), Notion (paper notes)","proTips":"Don't read papers cover-to-cover, read Abstract → Conclusion → Figures → Methods. Yannic Kilcher's channel is the best for paper walkthroughs. Subscribe to The Batch (Andrew Ng) and Import AI (Jack Clark).","resources":["r7add07d70","r28d957480","r105a5941c","r1c893562e","r34044e3eb","re9a5fa5ed","rb220d9156","r94edab61e","r32b9d4c78","r1acc1996a","re40520157","ra18c408c5","rc0a407bc6"]},{"id":"multimodal-vlms","topic":"Multimodal AI & Vision-Language Models","description":"Models that see and read at once. CLIP-style contrastive pretraining, vision-language models like LLaVA, and how image encoders get bolted onto LLMs. This is the layer behind screenshot understanding, visual search, and every model that answers questions about a photo.","phase":"depth-tracks","difficulty":"advanced","order":19,"week":19,"tools":"CLIP in a Colab notebook, LLaVA locally via Ollama, any frontier API with vision (all have free tiers)","proTips":"Start with CLIP zero-shot classification in Colab, it is ten lines of code and the aha moment of the whole field: images and text living in one embedding space. Everything else in multimodal is elaboration on that trick.","resources":["re05c06fb1","rdc3e08e6f","rfb98fb26d","r17a0f6635","r215892d03","r4ed6b7ecf","r85f05bde5","rc9c221b22","r02f37b525","rafd94ebb3","rab7f3097d"]},{"id":"speech-audio","topic":"Speech & Audio AI","description":"The ear and the voice: speech recognition (ASR) with models like Whisper, text-to-speech, speaker identification, and audio classification. Voice is becoming a default interface for AI, and the tooling is almost entirely open source.","phase":"depth-tracks","difficulty":"intermediate","order":20,"week":20,"tools":"Whisper (runs on a laptop), faster-whisper, Hugging Face pipelines, Audacity for inspecting audio","proTips":"Transcribe a podcast episode with Whisper on your own machine in week one, it works out of the box and makes the whole field concrete. Then learn what a mel spectrogram is: audio models are image models wearing headphones.","resources":["rfcd93f9a2","r719bd349c","rc5f38e7cc","r4ac1e208c","r4ec2b0f4f","r4a3141e52","r366536e70","rc8d87b4fd"]},{"id":"robotics-embodied","topic":"Robotics & Embodied AI","description":"AI that acts in the physical world. Simulation, reinforcement learning for control, imitation learning from teleoperation, and the new generation of vision-language-action models. The hardest open problem in AI, and the one hiring is quietly exploding around.","phase":"depth-tracks","difficulty":"advanced","order":21,"week":21,"tools":"MuJoCo (free), LeRobot, a SO-100/SO-101 arm kit if you want hardware for a few hundred dollars","proTips":"Simulation first: MuJoCo plus CS285 teaches you control without owning a robot. The field's big bet is that imitation learning plus VLA models does for robots what GPT did for text, watch pi.website and LeRobot to follow it live.","resources":["rb35c448b3","red4b2af34","rd36850544","r7824bc907","r2ed36b56a","rddd3756f8"]},{"id":"efficient-ai","topic":"Efficient AI · Quantization & Fast Inference","description":"Making models small and fast enough to actually ship: quantization, pruning, distillation, KV-cache management, speculative decoding, and serving engines like vLLM. The skills that turn a demo into a product with margins.","phase":"depth-tracks","difficulty":"advanced","order":22,"week":22,"tools":"llama.cpp, Ollama, vLLM, bitsandbytes, a consumer GPU or Apple Silicon Mac is genuinely enough","proTips":"Run a 7B model quantized to 4-bit on your own machine, then serve it with vLLM and measure tokens per second. Inference cost is the number that decides which AI products survive, engineers who can cut it are never unemployed.","resources":["r53fa6a918","rceaaacdb3","r86d115f7c","r0f9979cc4","r2f4c91280","r7d8321c30","r65e32dabe","rca4bfc039"]},{"id":"recommender-systems","topic":"Recommender Systems","description":"The most deployed ML on earth: every feed, storefront, and streaming queue. Collaborative filtering, matrix factorization, two-tower retrieval, and ranking. Quietly, it is also where many production ML careers actually happen.","phase":"depth-tracks","difficulty":"intermediate","order":23,"week":23,"tools":"pandas + scikit-learn for a first collaborative filter, the MovieLens dataset, implicit or torchrec when it gets real","proTips":"Build a MovieLens recommender from scratch before touching a library: user-item matrix, cosine similarity, done in an afternoon. Then read Google's course on why production recommenders are retrieval plus ranking, not one model.","resources":["r2127f1c84","r0fda86e5a","r083024947","ra950ed8bf","r9266e8109"]},{"id":"time-series","topic":"Time Series & Forecasting","description":"Predicting demand, traffic, revenue, and failures from data with a clock in it. Classical methods that still win (ARIMA, exponential smoothing), modern gradient-boosted and deep approaches, and the new pretrained forecasting models.","phase":"depth-tracks","difficulty":"intermediate","order":24,"week":24,"tools":"statsmodels, sktime, darts, Prophet for quick baselines, and always a naive-forecast baseline first","proTips":"The embarrassing secret of the field: a seasonal naive forecast beats fancy models on many real series. Always compute it first, and read Hyndman's fpp3 cover to cover, it is the rare free book that is also the field's standard reference.","resources":["r872f5cd33","r0bd3c6b70","ra5c6b25b3","r59c517f5e","r73162cdec","r0e3cbf23f"]},{"id":"graph-ml","topic":"Graph Machine Learning","description":"Learning on networks: fraud rings, molecules, knowledge graphs, social graphs, recommendation graphs. Graph neural networks, node embeddings, and message passing. The structure-aware corner of ML that tabular and text models cannot see.","phase":"depth-tracks","difficulty":"advanced","order":25,"week":25,"tools":"NetworkX for thinking, PyTorch Geometric for building, Neo4j free tier for a real graph database","proTips":"Start with the Distill article, it is the best visual explanation in the field. Then do Cora node classification in PyTorch Geometric, the MNIST of graphs. This site's own Graph Types for AI Agents teardown pairs well as the applied view.","resources":["rcaa15f06d","r65ef80021","r63ebbb762","r77529d058","r8f917d7a9","r0451d6490"]}];
